/** Expanded, ready-to-use `GroceryDBEntry` records. */
export const SEED_ENTRIES = Object.entries(SEED).flatMap(([category, rows]) =>
  rows.map(([name, emoji, unitOverride, ...synonyms]) => ({
    id: `seed:${slugify(name)}`,
    name,
    matchTerms: expandTerms(name, ...synonyms),
    category,
    emoji: emoji || null,
    defaultUnit: unitOverride || categoryDefaultUnit(category),
    isCustom: false,
  })),
);
